const { CodeBuildClient, StartBuildCommand, BatchGetBuildsCommand } = require('@aws-sdk/client-codebuild');
const codebuild = new CodeBuildClient();

exports.handler = async function(event, context) {
  const props = event.ResourceProperties;
  const requestType = event.RequestType;

  // Build the response object
  const response = {
    Status: 'SUCCESS',
    PhysicalResourceId: props.ImageUri || 'container-build',
    StackId: event.StackId,
    RequestId: event.RequestId,
    LogicalResourceId: event.LogicalResourceId,
    Data: {},
  };

  try {
    if (requestType === 'Delete') {
      response.Data = {};
      await sendResponse(event, response);
      return;
    }

    // Docker build args: forward each as its own build environment variable and reference it with
    // '--build-arg NAME' (no value), so docker inherits the value from the environment. This keeps
    // arbitrary values off the shell command line (no quoting/word-splitting hazards). BUILD_ARG_FLAGS
    // is the space-separated flag list the buildspec interpolates; it is empty when there are no args.
    const buildArgs = props.BuildArgs ? JSON.parse(props.BuildArgs) : {};
    const buildArgNames = Object.keys(buildArgs);
    const buildArgEnv = buildArgNames.map(name => ({ name, value: String(buildArgs[name]), type: 'PLAINTEXT' }));
    const buildArgFlags = buildArgNames.map(name => '--build-arg ' + name).join(' ');

    // Start CodeBuild
    const startResult = await codebuild.send(new StartBuildCommand({
      projectName: props.ProjectName,
      sourceTypeOverride: 'S3',
      sourceLocationOverride: props.SourceBucket + '/' + props.SourceKey,
      environmentVariablesOverride: [
        { name: 'ECR_REGISTRY', value: props.EcrRegistry, type: 'PLAINTEXT' },
        { name: 'IMAGE_URI', value: props.ImageUri, type: 'PLAINTEXT' },
        { name: 'DOCKERFILE_PATH', value: props.DockerfilePath, type: 'PLAINTEXT' },
        { name: 'BUILD_ARG_FLAGS', value: buildArgFlags, type: 'PLAINTEXT' },
        ...buildArgEnv,
      ],
    }));

    const buildId = startResult.build.id;
    console.log('Started build:', buildId);

    // Poll until complete (14 minutes max to stay within Lambda's 15-minute timeout)
    const maxWaitMs = 14 * 60 * 1000;
    const start = Date.now();
    while (Date.now() - start < maxWaitMs) {
      const result = await codebuild.send(new BatchGetBuildsCommand({ ids: [buildId] }));
      const build = result.builds[0];
      if (build.buildStatus !== 'IN_PROGRESS') {
        if (build.buildStatus === 'SUCCEEDED') {
          response.Data = { ContainerUri: props.ImageUri };
          await sendResponse(event, response);
          return;
        } else {
          const logsUrl = build.logs && build.logs.deepLink ? build.logs.deepLink : 'Check CloudWatch Logs';
          response.Status = 'FAILED';
          response.Reason = 'CodeBuild build failed. Status: ' + build.buildStatus + '. Logs: ' + logsUrl;
          await sendResponse(event, response);
          return;
        }
      }
      await new Promise(r => setTimeout(r, 10000));
    }

    response.Status = 'FAILED';
    response.Reason = 'Build timed out after 14 minutes';
    await sendResponse(event, response);
  } catch (err) {
    response.Status = 'FAILED';
    response.Reason = err.message || 'Unknown error';
    await sendResponse(event, response);
  }
};

async function sendResponse(event, response) {
  const https = require('https');
  const responseBody = JSON.stringify(response);
  const parsedUrl = new URL(event.ResponseURL);
  const options = {
    hostname: parsedUrl.hostname,
    port: 443,
    path: parsedUrl.pathname + parsedUrl.search,
    method: 'PUT',
    headers: { 'content-type': '', 'content-length': responseBody.length },
  };
  return new Promise((resolve, reject) => {
    const req = https.request(options, resolve);
    req.on('error', reject);
    req.write(responseBody);
    req.end();
  });
}

