        "echo \"Building container image...\"",
        "docker build -t $IMAGE_URI -f $DOCKERFILE_PATH $BUILD_ARG_FLAGS ."
      ]
    },
    "post_build": {
      "commands": [
        "echo \"Pushing image to ECR...\"",
        "docker push $IMAGE_URI",
        "echo \"Image pushed: $IMAGE_URI\""
      ]
    }
  }
